module adder_pipe_64bit(
    input clk, rst_n, i_en,
    input [63:0] adda, addb,
    output [64:0] result,
    output o_en
);

    reg [15:0] adda_reg [3:0];
    reg [15:0] addb_reg [3:0];
    reg [15:0] carry_in_reg [3:0];
    reg [15:0] carry_out_reg [3:0];
    reg [63:0] sum_reg [3:0];
    reg o_en_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (integer i = 0; i < 4; i = i + 1) begin
                adda_reg[i] <= 16'b0;
                addb_reg[i] <= 16'b0;
                carry_in_reg[i] <= 16'b0;
                carry_out_reg[i] <= 16'b0;
                sum_reg[i] <= 64'b0;
            end
            o_en_reg <= 1'b0;
        end else if (i_en) begin
            adda_reg[0] <= adda[15:0];
            addb_reg[0] <= addb[15:0];
            carry_in_reg[0] <= 16'b0;
            {carry_out_reg[0], sum_reg[0]} <= adda_reg[0] + addb_reg[0];
            for (integer i = 1; i < 4; i = i + 1) begin
                adda_reg[i] <= adda[15:0 + 16*i];
                addb_reg[i] <= addb[15:0 + 16*i];
                carry_in_reg[i] <= {carry_out_reg[i-1]};
                {carry_out_reg[i], sum_reg[i]} <= adda_reg[i] + addb_reg[i] + carry_in_reg[i];
            end
            o_en_reg <= 1'b1;
        end else begin
            o_en_reg <= 1'b0;
        end
    end

    assign result = {carry_out_reg[3], sum_reg[3]};
    assign o_en = o_en_reg;

endmodule
